+import { afterEach, describe, it, expect, vi } from 'vitest';
+import { resolveDatabaseUrl } from '../src/core/config.ts';
+
+afterEach(() => vi.unstubAllEnvs());
+
+function stubComponents(overrides: Record<string, string> = {}) {
+  const values: Record<string, string> = {
+    DATABASE_URL: '',
+    POSTGRES_USER: 'u',
+    POSTGRES_PASSWORD: 'p',
+    POSTGRES_HOST: 'h',
+    DB_PORT: '5432',
+    POSTGRES_DB: 'd',
+    ...overrides,
+  };
+  for (const [name, value] of Object.entries(values)) vi.stubEnv(name, value);
+}
+
+describe('resolveDatabaseUrl', () => {
+  it('rewrites the SQLAlchemy psycopg scheme', () => {
+    stubComponents({ DATABASE_URL: 'postgresql+psycopg://u:p@h:5432/d' });
+    expect(resolveDatabaseUrl()).toBe('postgresql://u:p@h:5432/d');
+  });
+  it('prefers an explicit override over DATABASE_URL', () => {
+    stubComponents({ DATABASE_URL: 'postgresql://env:p@h:5432/env' });
+    expect(resolveDatabaseUrl('postgresql://override:p@h:5432/over')).toBe('postgresql://override:p@h:5432/over');
+  });
+  it('builds a URL from components with encoded credentials', () => {
+    stubComponents({ POSTGRES_PASSWORD: 'p@ss/word', POSTGRES_DB: 'my db' });
+    const url = new URL(resolveDatabaseUrl());
+    expect(url.protocol).toBe('postgresql:');
+    expect(decodeURIComponent(url.username)).toBe('u');
+    expect(decodeURIComponent(url.password)).toBe('p@ss/word');
+    expect(url.hostname).toBe('h');
+    expect(url.port).toBe('5432');
+    expect(decodeURIComponent(url.pathname)).toBe('/my db');
+  });
+  it('names the missing environment variable', () => {
+    stubComponents({ POSTGRES_HOST: '' });
+    expect(() => resolveDatabaseUrl()).toThrow('Missing environment variable: POSTGRES_HOST');
+  });
+});
