+import { it, expect, vi } from 'vitest';
+import { initialize } from '../src/core/database.ts';
+import type { Database } from '../src/features/todos/types.ts';
+
+it('issues one CREATE TABLE IF NOT EXISTS statement with the todo schema obligations', async () => {
+  const executeRaw = vi.fn().mockResolvedValue(0);
+  await initialize({ $executeRaw: executeRaw } as unknown as Database);
+
+  expect(executeRaw).toHaveBeenCalledTimes(1);
+  const [strings, ...values] = executeRaw.mock.calls[0];
+  expect(values).toEqual([]);
+  const sql = (strings as string[]).join('').replace(/\s+/g, ' ');
+
+  expect(sql).toMatch(/CREATE TABLE IF NOT EXISTS todos/);
+  expect(sql).toMatch(/\bid SERIAL PRIMARY KEY/);
+  expect(sql).toMatch(/\btitle VARCHAR\(120\) NOT NULL/);
+  expect(sql).toMatch(/\bdescription VARCHAR\(2000\) NOT NULL/);
+  expect(sql).toMatch(/\bpriority VARCHAR\(6\) NOT NULL/);
+  expect(sql).toMatch(/\bdue_date DATE\b/);
+  expect(sql).toMatch(/\bcompleted BOOLEAN NOT NULL/);
+  expect(sql).toMatch(/\bcreated_at TIMESTAMPTZ NOT NULL/);
+  expect(sql).toMatch(/\bupdated_at TIMESTAMPTZ NOT NULL/);
+  expect(sql).toMatch(/todo_title_not_empty CHECK \(length\(title\) >= 1\)/);
+  expect(sql).toMatch(/todo_priority CHECK \(priority IN \('low', ?'medium', ?'high'\)\)/);
+});
