+import request from 'supertest';
+import { afterEach, describe, expect, it, vi } from 'vitest';
+import { createApp } from '../src/factory.ts';
+import type { Database } from '../src/features/todos/types.ts';
+
+const specification = { openapi: '3.0.0', info: { title: 'Stub API', version: '9.9.9' }, paths: { '/api/todos': {} } };
+
+vi.mock('node:fs', async (importOriginal) => {
+  const actual = await importOriginal<typeof import('node:fs')>();
+  return {
+    ...actual,
+    readFileSync: vi.fn((path: unknown, ...rest: unknown[]) =>
+      String(path).endsWith('openapi.json')
+        ? JSON.stringify(specification)
+        : (actual.readFileSync as (...args: unknown[]) => unknown)(path, ...rest)),
+  };
+});
+
+afterEach(() => vi.restoreAllMocks());
+
+function setup(findMany = vi.fn().mockResolvedValue([])) {
+  const database = {
+    todo: { findFirst: vi.fn().mockResolvedValue(null), findMany, create: vi.fn() },
+  } as unknown as Database;
+  return { app: createApp(database), database, findMany };
+}
+
+describe('createApp error handling', () => {
+  it('returns JSON errors for unknown routes, malformed JSON and oversized bodies', async () => {
+    const { app, database } = setup();
+
+    const missing = await request(app).get('/nope');
+    expect(missing.status).toBe(404);
+    expect(missing.body).toEqual({ detail: 'Not Found' });
+    expect(missing.headers['x-powered-by']).toBeUndefined();
+
+    const malformed = await request(app).post('/api/todos').set('Content-Type', 'application/json').send('{bad');
+    expect(malformed.status).toBe(422);
+    expect(malformed.body).toEqual({ detail: 'Invalid JSON.' });
+
+    const oversized = await request(app)
+      .post('/api/todos')
+      .set('Content-Type', 'application/json')
+      .send(JSON.stringify({ title: 'x'.repeat(150_000) }));
+    expect(oversized.status).toBe(413);
+    expect(oversized.body).toEqual({ detail: 'Request body too large.' });
+
+    expect(database.todo.create).not.toHaveBeenCalled();
+  });
+
+  it('hides unexpected error details behind a generic 500 and logs them', async () => {
+    const failure = new Error('secret');
+    const consoleError = vi.spyOn(console, 'error').mockImplementation(() => {});
+    const { app } = setup(vi.fn().mockRejectedValue(failure));
+
+    const response = await request(app).get('/api/todos');
+    expect(response.status).toBe(500);
+    expect(response.body).toEqual({ detail: 'Internal Server Error' });
+    expect(response.text).not.toContain('secret');
+    expect(consoleError).toHaveBeenCalledWith(failure);
+  });
+
+  it('serves the loaded OpenAPI specification', async () => {
+    const { app } = setup();
+    const response = await request(app).get('/openapi.json');
+    expect(response.status).toBe(200);
+    expect(response.body).toEqual(specification);
+  });
+});
