+import { afterEach, expect, it, vi } from 'vitest'
+import { request } from './http'
+
+afterEach(() => vi.unstubAllGlobals())
+
+function stubResponse(response: {
+  status: number
+  ok: boolean
+  json: () => Promise<unknown>
+}) {
+  const fetchMock = vi.fn().mockResolvedValue(response)
+  vi.stubGlobal('fetch', fetchMock)
+  return fetchMock
+}
+
+it('reports a connection failure with a friendly message', async () => {
+  vi.stubGlobal('fetch', vi.fn().mockRejectedValue(new TypeError('boom')))
+  await expect(request('/todos')).rejects.toThrow(
+    'Cannot connect to the server. Please try again.',
+  )
+})
+
+it('rethrows the original error when the request was aborted', async () => {
+  const controller = new AbortController()
+  const abortError = new DOMException('Aborted', 'AbortError')
+  controller.abort()
+  vi.stubGlobal('fetch', vi.fn().mockRejectedValue(abortError))
+  await expect(
+    request('/todos', { signal: controller.signal }),
+  ).rejects.toBe(abortError)
+})
+
+it('maps a 422 response to the task validation message', async () => {
+  stubResponse({
+    status: 422,
+    ok: false,
+    json: async () => ({ detail: [{ msg: 'internal' }] }),
+  })
+  await expect(request('/todos')).rejects.toThrow(/Check the task details/)
+})
+
+it('surfaces a string detail from a failed response', async () => {
+  stubResponse({
+    status: 400,
+    ok: false,
+    json: async () => ({ detail: 'Nope' }),
+  })
+  await expect(request('/todos')).rejects.toThrow('Nope')
+})
+
+it.each([
+  ['a non-JSON body', () => Promise.reject(new SyntaxError('bad json'))],
+  ['a non-string detail', async () => ({ detail: { code: 1 } })],
+])('uses the generic failure message for %s', async (_name, json) => {
+  stubResponse({ status: 500, ok: false, json })
+  await expect(request('/todos')).rejects.toThrow(
+    'The operation failed. Please try again.',
+  )
+})
+
+it('prefixes /api and merges the JSON content type with caller headers', async () => {
+  const fetchMock = stubResponse({
+    status: 200,
+    ok: true,
+    json: async () => ({ a: 1 }),
+  })
+  await expect(
+    request('/path', { method: 'POST', headers: { 'X-Test': '1' } }),
+  ).resolves.toEqual({ a: 1 })
+  expect(fetchMock).toHaveBeenCalledTimes(1)
+  const [url, init] = fetchMock.mock.calls[0]
+  expect(url).toBe('/api/path')
+  expect(init.method).toBe('POST')
+  expect(init.headers).toEqual({
+    'Content-Type': 'application/json',
+    'X-Test': '1',
+  })
+})
+
+it('resolves undefined for 204 without reading a body', async () => {
+  const json = vi.fn().mockRejectedValue(new SyntaxError('no body'))
+  stubResponse({ status: 204, ok: true, json })
+  await expect(request('/todos/7', { method: 'DELETE' })).resolves.toBeUndefined()
+  expect(json).not.toHaveBeenCalled()
+})
